==> V30__person_hold.sql <==
-- A hold has a from-date and an optional to-date (null: open-ended), and a person may have several
-- over time. Only their OPEN and PENDING claims dated within a hold, and not bound by a statement,
-- are left out of the live totals. A person on hold before this kept it for all dates: their hold
-- now runs from the earliest date there is.
CREATE TABLE person_hold (
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE   NOT NULL,
    to_date   DATE,
    CHECK (to_date IS NULL OR to_date >= from_date)
);
INSERT INTO person_hold (person_id, from_date, to_date)
    SELECT id, DATE '0001-01-01', NULL FROM person WHERE held;

==> V31__rate_to.sql <==
-- A rate may carry a to-date: it applies through it, and a claim dated after it has no rate unless a
-- later rate of the grade is in force on its date. A rate with no to-date applies until the next
-- rate's from-date. A to-date is never before the rate's from-date.
ALTER TABLE rate ADD COLUMN to_date DATE;
ALTER TABLE rate ADD CONSTRAINT rate_to_after_from CHECK (to_date IS NULL OR from_date IS NULL OR to_date >= from_date);

==> V32__sheet_cap.sql <==
-- The sheet's cap: a person's due-total is at most it, the excess shown apart. Null means no cap.
ALTER TABLE sheet ADD COLUMN cap DECIMAL(14, 2);

==> V33__period_person_total.sql <==
-- Closing a period also fixes each person's due-total for it at that moment, one row per person then
-- on the sheet; a person added later has no row and shows 0.00 for it. Reopening removes the rows.
-- The period's closed_total is the sum of these.
CREATE TABLE period_person_total (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL,
    total     DECIMAL(14, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);

==> V34__sheet_setting_from.sql <==
-- Dated settings: a setting that carries a figure (the floor, the late percent, the terms, each
-- grade's terms, the clerk limit and the cap) holds a value per from-date. The value in force on a
-- date is the one with the latest from-date on or before it; before every from-date it is the
-- sheet's own column (its starting value). A sheet holds at most one value per key and from-date.
-- A null value means none (no limit, no cap, or the sheet's terms for a grade).
CREATE TABLE sheet_setting (
    sheet_id      VARCHAR(64) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(32) NOT NULL,
    from_date     DATE        NOT NULL,
    setting_value VARCHAR(32)
);
CREATE UNIQUE INDEX sheet_setting_key_from ON sheet_setting (sheet_id, setting_key, from_date);

==> V35__claim_deferred.sql <==
-- An OPEN claim may be deferred to a date after the sheet's today: until the sheet's today reaches
-- it, the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
-- statement. Null when never deferred; the date is kept once reached.
ALTER TABLE claim ADD COLUMN deferred_until DATE;

==> V36__claim_proofs.sql <==
-- A claim's proofs count, raised by one at a time while the claim is neither SETTLED nor VOID.
ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
-- The sheet's starting proof threshold (before every from-date, see sheet_setting): a claim whose
-- due is above the threshold in force on its date cannot be settled or approved with no proofs.
-- Null means none.
ALTER TABLE sheet ADD COLUMN proof_threshold DECIMAL(14, 2);

==> V37__sheet_permission.sql <==
-- The permission matrix: for an action (open, settle, void, reassign, close, reopen), the roles that
-- may take it, as a comma separated list. An action with no row keeps its standing rule.
CREATE TABLE sheet_permission (
    sheet_id    VARCHAR(64) NOT NULL REFERENCES sheet (id),
    action      VARCHAR(16) NOT NULL,
    roles       VARCHAR(64) NOT NULL
);
CREATE UNIQUE INDEX sheet_permission_action ON sheet_permission (sheet_id, action);

