UPDATE sheet_role SET next_role = role;
ALTER TABLE sheet_role DROP COLUMN role;
ALTER TABLE sheet_role ALTER COLUMN next_role RENAME TO role;
ALTER TABLE sheet_role ALTER COLUMN role DROP DEFAULT;

